import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import process from "node:process";
import { URL, fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { checkRustixLock, isAffectedRustixVersion, RUSTIX_ADVISORY } from "./check-rustix-advisory.mjs";

const lock = version => [
  "# This file is automatically generated.",
  "version = 4", "",
  "[[package]]", 'name = "eyezen"', 'version = "1.2.2"', "",
  "[[package]]", 'name = "rustix"', 'version = "' + version + '"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"', "",
].join("\n");

describe("rustix unsoundness advisory lockfile guard", () => {
  it("accepts the exact patched 1.1.6 boundary and newer versions", () => {
    for (const version of ["0.99.1", "1.1.6", "1.1.7", "1.2.0", "2.0.0"]) {
      expect(isAffectedRustixVersion(version), version).toBe(false);
      expect(checkRustixLock(lock(version)), version).toEqual([version]);
    }
  });

  it("rejects the vulnerable range and unverified first-fixed prereleases", () => {
    for (const version of ["1.0.0", "1.0.9", "1.1.0", "1.1.5", "1.1.6-rc.1"]) {
      expect(isAffectedRustixVersion(version), version).toBe(true);
      expect(() => checkRustixLock(lock(version))).toThrow(RUSTIX_ADVISORY);
    }
  });

  it("fails closed on malformed lockfiles and unknown rustix versions", () => {
    expect(() => checkRustixLock(null)).toThrow();
    expect(() => checkRustixLock("# no packages\nversion = 4")).toThrow();
    expect(() => checkRustixLock(lock("1.1"))).toThrow(/malformed/);
    expect(() => checkRustixLock(lock("v1.1.5"))).toThrow(/malformed/);
    expect(() => checkRustixLock(lock("99999999999999999999.1.1"))).toThrow(/oversized/);
    expect(() => checkRustixLock(lock("1.1.5").replace('version = "1.1.5"', ""))).toThrow(/no version/);
  });

  it("rejects any nested affected copy while allowing no rustix packages", () => {
    expect(checkRustixLock(lock("1.1.6").replace(/(?:\r?\n)?\[\[package\]\]\nname = "rustix"[\s\S]*/, ""))).toEqual([]);
    const mixed = lock("1.1.6") + '\n[[package]]\nname = "rustix"\nversion = "1.1.5"\n';
    expect(() => checkRustixLock(mixed)).toThrow(RUSTIX_ADVISORY);
  });

  it("exercises the exact CLI used by CI with exit-code behavior", () => {
    const script = fileURLToPath(new URL("./check-rustix-advisory.mjs", import.meta.url));
    const dir = mkdtempSync(path.join(tmpdir(), "eyezen-rustix-audit-"));
    try {
      const p = path.join(dir, "Cargo.lock");
      writeFileSync(p, lock("1.1.6"));
      const good = spawnSync(process.execPath, [script, p], { encoding: "utf8" });
      expect(good.status).toBe(0);
      expect(good.stdout).toContain(RUSTIX_ADVISORY);
      writeFileSync(p, lock("1.1.5"));
      const bad = spawnSync(process.execPath, [script, p], { encoding: "utf8" });
      expect(bad.status).toBe(1);
      expect(bad.stderr).toContain(RUSTIX_ADVISORY);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
